//! OCR benchmark: ground-truth corpus + Windows.Media.Ocr throughput and accuracy.
//!
//! Speed and accuracy are reported separately and never conflated:
//!   - speed: session open ms, per-image ms (p50/p95/p99), images/sec cold/warm
//!   - accuracy: character error rate (CER) vs known ground-truth text, plus
//!     normalized exact-match rate, per scenario.
//! OCR runs on synthetic rendered images generated by tools/ocr/gen_ocr_corpus.ps1
//! (GNI+ text, not photographs/scans); that limitation is reported.
//!
//! If Windows.Media.Ocr is unavailable the report status is "unverified" and the
//! harness exits successfully with an explicit UNVERIFIED message. No numbers are
//! synthesized.
//!
//! OWNER: perf-bench.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Barrier;
use std::time::Instant;

use serde::{Deserialize, Serialize};

use crate::args::Args;
use crate::env::{hidden_command, host_info, self_memory, ProcessMemory};
use crate::stats::{summarize, Summary};
use crate::{write_json, RESULT_SCHEMA};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ManifestEntry {
    pub file: String,
    pub text: String,
    pub scenario: String,
    pub font: String,
    pub px: u32,
    pub width: u32,
    pub height: u32,
}

pub fn load_manifest(path: &Path) -> anyhow::Result<Vec<ManifestEntry>> {
    let text = std::fs::read_to_string(path)?;
    let text = text.strip_prefix('\u{feff}').unwrap_or(&text);
    let mut out = Vec::new();
    for (i, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        out.push(
            serde_json::from_str(line).map_err(|e| anyhow::anyhow!("{}:{}: {e}", path.display(), i + 1))?,
        );
    }
    anyhow::ensure!(!out.is_empty(), "empty OCR manifest: {}", path.display());
    Ok(out)
}

/// Generate the corpus by invoking the committed PowerShell GDI+ script.
pub fn generate_corpus(out_dir: &Path, script: &Path, count: usize) -> anyhow::Result<usize> {
    anyhow::ensure!(
        script.exists(),
        "OCR corpus generator script not found: {}",
        script.display()
    );
    if let Some(dir) = out_dir.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let mut cmd = hidden_command("powershell.exe");
    cmd.args([
        "-NoProfile",
        "-NonInteractive",
        "-ExecutionPolicy",
        "Bypass",
        "-File",
    ]);
    cmd.arg(script);
    cmd.arg("-OutDir");
    cmd.arg(out_dir);
    cmd.arg("-Count");
    cmd.arg(count.to_string());
    let out = cmd.output()?;
    println!("{}", String::from_utf8_lossy(&out.stdout).trim());
    if !out.status.success() {
        anyhow::bail!(
            "OCR corpus generation failed (exit {:?}): {}",
            out.status.code(),
            String::from_utf8_lossy(&out.stderr)
        );
    }
    let manifest = out_dir.join("manifest.jsonl");
    let entries = load_manifest(&manifest)?;
    Ok(entries.len())
}

fn is_cjk(c: char) -> bool {
    crate::dataset::is_cjk(c)
}

/// Normalize for CER: lowercase, alphanumerics/CJK only, single spaces.
pub fn normalize(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut prev_space = true;
    for c in s.chars() {
        let c = c.to_lowercase().next().unwrap_or(c);
        if c.is_alphanumeric() || is_cjk(c) {
            out.push(c);
            prev_space = false;
        } else if !prev_space {
            out.push(' ');
            prev_space = true;
        }
    }
    out.trim().to_string()
}

/// Character error rate via Levenshtein distance over normalized text.
pub fn cer(ground_truth: &str, recognized: &str) -> (f64, usize, usize) {
    let a: Vec<char> = normalize(ground_truth).chars().collect();
    let b: Vec<char> = normalize(recognized).chars().collect();
    let dist = levenshtein(&a, &b);
    let denom = a.len().max(1);
    (dist as f64 / denom as f64, dist, a.len())
}

fn levenshtein(a: &[char], b: &[char]) -> usize {
    if a.is_empty() {
        return b.len();
    }
    if b.is_empty() {
        return a.len();
    }
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for (i, ca) in a.iter().enumerate() {
        cur[0] = i + 1;
        for (j, cb) in b.iter().enumerate() {
            let cost = if ca == cb { 0 } else { 1 };
            cur[j + 1] = (prev[j + 1] + 1).min(cur[j] + 1).min(prev[j] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

#[cfg(windows)]
mod winrt_ocr {
    use std::path::Path;

    use windows::Graphics::Imaging::BitmapDecoder;
    use windows::Media::Ocr::OcrEngine;
    use windows::Storage::Streams::{DataWriter, InMemoryRandomAccessStream};

    fn to_anyhow(err: windows::core::Error) -> anyhow::Error {
        anyhow::anyhow!("Windows.Media.Ocr: {err}")
    }

    pub struct Session {
        engine: OcrEngine,
    }

    impl Session {
        pub fn open() -> anyhow::Result<Self> {
            let engine = OcrEngine::TryCreateFromUserProfileLanguages().map_err(to_anyhow)?;
            Ok(Self { engine })
        }

        pub fn language(&self) -> String {
            self.engine
                .RecognizerLanguage()
                .ok()
                .and_then(|l| l.LanguageTag().ok())
                .map(|tag| tag.to_string())
                .unwrap_or_else(|| "unknown".to_string())
        }

        pub fn recognize(&self, path: &Path) -> anyhow::Result<String> {
            // Read bytes with std::fs and decode from an in-memory WinRT stream.
            // StorageFile::GetFileFromPathAsync goes through the Storage broker and
            // is denied for processes launched by the agent harness; an in-process
            // in-memory stream has no such ACL dependency.
            let bytes =
                std::fs::read(path).map_err(|e| anyhow::anyhow!("read image {}: {e}", path.display()))?;
            let stream = InMemoryRandomAccessStream::new().map_err(to_anyhow)?;
            let writer = DataWriter::CreateDataWriter(&stream).map_err(to_anyhow)?;
            writer.WriteBytes(&bytes).map_err(to_anyhow)?;
            writer.StoreAsync().map_err(to_anyhow)?.get().map_err(to_anyhow)?;
            stream.Seek(0).map_err(to_anyhow)?;
            let decoder = BitmapDecoder::CreateAsync(&stream)
                .map_err(to_anyhow)?
                .get()
                .map_err(to_anyhow)?;
            let bitmap = decoder
                .GetSoftwareBitmapAsync()
                .map_err(to_anyhow)?
                .get()
                .map_err(to_anyhow)?;
            let result = self
                .engine
                .RecognizeAsync(&bitmap)
                .map_err(to_anyhow)?
                .get()
                .map_err(to_anyhow)?;
            Ok(result.Text().map_err(to_anyhow)?.to_string())
        }
    }

    pub fn available_languages() -> Vec<String> {
        let mut out: Vec<String> = Vec::new();
        if let Ok(engine) = OcrEngine::TryCreateFromUserProfileLanguages() {
            if let Ok(lang) = engine.RecognizerLanguage() {
                if let Ok(tag) = lang.LanguageTag() {
                    out.push(tag.to_string());
                }
            }
        }
        if let Ok(langs) = OcrEngine::AvailableRecognizerLanguages() {
            if let Ok(n) = langs.Size() {
                for i in 0..n {
                    if let Ok(lang) = langs.GetAt(i) {
                        if let Ok(tag) = lang.LanguageTag() {
                            let s = tag.to_string();
                            if !out.contains(&s) {
                                out.push(s);
                            }
                        }
                    }
                }
            }
        }
        out
    }
}

#[cfg(not(windows))]
mod winrt_ocr {
    use std::path::Path;

    pub struct Session;

    impl Session {
        pub fn open() -> anyhow::Result<Self> {
            anyhow::bail!("Windows.Media.Ocr is unavailable on this platform")
        }
        pub fn language(&self) -> String {
            "unknown".to_string()
        }
        pub fn recognize(&self, _path: &Path) -> anyhow::Result<String> {
            anyhow::bail!("Windows.Media.Ocr is unavailable on this platform")
        }
    }

    pub fn available_languages() -> Vec<String> {
        Vec::new()
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct ImageResult {
    pub file: String,
    pub scenario: String,
    pub pass: usize,
    pub ms: f64,
    pub cer: f64,
    pub errors: usize,
    pub chars: usize,
    pub exact: bool,
    pub ground_truth: String,
    pub recognized: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct ScenarioRow {
    pub scenario: String,
    pub images: usize,
    pub mean_cer: f64,
    pub exact_rate: f64,
    pub mean_ms: Summary,
}

#[derive(Debug, Clone, Serialize)]
pub struct PassReport {
    pub pass: usize,
    pub images: usize,
    pub wall_ms: f64,
    pub images_per_sec: f64,
    pub latency: Summary,
    pub mean_cer: f64,
    pub median_cer: f64,
    pub exact_rate: f64,
    pub total_chars: usize,
    pub total_errors: usize,
    pub image_errors: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct OcrReport {
    pub schema: String,
    pub kind: String,
    pub status: String,
    pub reason: String,
    pub host: crate::env::HostInfo,
    pub generated_at_utc: String,
    pub command: String,
    pub engine: String,
    pub languages: Vec<String>,
    pub session_open_ms: f64,
    pub passes: Vec<PassReport>,
    pub by_scenario: Vec<ScenarioRow>,
    pub per_image: Vec<ImageResult>,
    pub memory_after: Option<ProcessMemory>,
    pub limitations: Vec<String>,
}

fn now_utc() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    format!("unix:{secs}")
}

/// One OCR call made by a worker: recognized text or error text, plus latency.
struct Recognition {
    outcome: Result<String, String>,
    ms: f64,
}

/// One pass over `paths` on `threads` workers. Each worker opens its own engine on
/// its own thread (engine objects are not shared across threads). The timed window
/// starts once every engine is open, so engine creation does not count against
/// throughput. Returns results in input order and the window's wall time in ms.
/// Text of one image: Windows.Media.Ocr when a session is given, otherwise the ps-ocr
/// engine `engine`, called the same way the index calls it.
#[cfg(feature = "ocr")]
fn recognize_image(engine: &str, model_dir: Option<&Path>, session: Option<&winrt_ocr::Session>, path: &Path) -> Result<String, String> {
    match session {
        Some(session) => session.recognize(path).map_err(|err| format!("{err}")),
        None => ps_ocr::extract_image_with_engine(path, 16_777_216, engine, model_dir)
            .map(|found| found.map(|doc| doc.text).unwrap_or_default())
            .map_err(|err| format!("{err:#}")),
    }
}

#[cfg(not(feature = "ocr"))]
fn recognize_image(_engine: &str, _model_dir: Option<&Path>, session: Option<&winrt_ocr::Session>, path: &Path) -> Result<String, String> {
    match session {
        Some(session) => session.recognize(path).map_err(|err| format!("{err}")),
        None => Err("ps-bench was built without the ocr feature".to_string()),
    }
}

/// One pass over `paths` on `threads` workers with `engine` ("windows" or a ps-ocr engine id).
fn recognize_pass(paths: &[PathBuf], threads: usize, engine: &str, model_dir: Option<&Path>) -> (Vec<Recognition>, f64) {
    let next = AtomicUsize::new(0);
    let ready = Barrier::new(threads + 1);
    std::thread::scope(|scope| {
        let workers: Vec<_> = (0..threads)
            .map(|_| {
                scope.spawn(|| {
                    let session = if engine == "windows" {
                        winrt_ocr::Session::open().map(Some).map_err(|err| format!("{err}"))
                    } else {
                        Ok(None)
                    };
                    ready.wait();
                    let mut done = Vec::new();
                    loop {
                        let index = next.fetch_add(1, Ordering::Relaxed);
                        let Some(path) = paths.get(index) else { break };
                        let recognition = match &session {
                            Ok(session) => {
                                let start = Instant::now();
                                let outcome = recognize_image(engine, model_dir, session.as_ref(), path);
                                Recognition { outcome, ms: start.elapsed().as_secs_f64() * 1000.0 }
                            }
                            Err(err) => Recognition { outcome: Err(err.clone()), ms: 0.0 },
                        };
                        done.push((index, recognition));
                    }
                    done
                })
            })
            .collect();
        ready.wait();
        let started = Instant::now();
        let mut all: Vec<(usize, Recognition)> = workers
            .into_iter()
            .flat_map(|worker| worker.join().expect("OCR worker panicked"))
            .collect();
        let wall_ms = started.elapsed().as_secs_f64() * 1000.0;
        all.sort_by_key(|(index, _)| *index);
        (all.into_iter().map(|(_, recognition)| recognition).collect(), wall_ms)
    })
}

pub fn run(args: &Args) -> anyhow::Result<()> {
    let manifest_path = PathBuf::from(
        args.get("--manifest")
            .unwrap_or(".bench/ocr-corpus/manifest.jsonl"),
    );
    let out = PathBuf::from(args.required("--out")?);
    let passes = args.usize_or("--passes", 2)?.max(1);
    let threads = args.usize_or("--threads", 1)?.max(1);
    let limit = args.usize_or("--limit", 0)?;
    // "windows" is Windows.Media.Ocr; any other id is a ps-ocr engine. pp_ocr_v6 and indra
    // read their packs from <--models>/ppocrv6 and <--models>/indra (the app's models folder).
    let engine_id = args.get("--engine").unwrap_or("windows").to_string();
    let engine_label = if engine_id == "windows" { "windows.media.ocr".to_string() } else { engine_id.clone() };
    let model_dir = match engine_id.as_str() {
        "pp_ocr_v6" => Some(PathBuf::from(args.required("--models")?).join("ppocrv6")),
        "indra" => Some(PathBuf::from(args.required("--models")?).join("indra")),
        _ => None,
    };
    let manifest_path = if manifest_path.is_absolute() {
        manifest_path
    } else {
        std::env::current_dir()?.join(&manifest_path)
    };
    let manifest = load_manifest(&manifest_path)?;
    let base_dir = manifest_path
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| PathBuf::from("."));
    let subset: Vec<&ManifestEntry> = if limit > 0 {
        manifest.iter().take(limit).collect()
    } else {
        manifest.iter().collect()
    };

    let languages = winrt_ocr::available_languages();
    let session_open_start = Instant::now();
    let session = match winrt_ocr::Session::open() {
        Ok(session) => session,
        Err(err) => {
            let report = OcrReport {
                schema: RESULT_SCHEMA.to_string(),
                kind: "ocr-benchmark".to_string(),
                status: "unverified".to_string(),
                reason: format!("Windows.Media.Ocr unavailable on this host: {err}"),
                host: host_info().clone(),
                generated_at_utc: now_utc(),
                command: format!(
                    "ps-bench ocr --manifest {} --out {}",
                    manifest_path.display(),
                    out.display()
                ),
                engine: "windows.media.ocr".to_string(),
                languages,
                session_open_ms: 0.0,
                passes: Vec::new(),
                by_scenario: Vec::new(),
                per_image: Vec::new(),
                memory_after: self_memory(),
                limitations: vec!["OCR could not be exercised; report is explicitly UNVERIFIED".to_string()],
            };
            write_json(&out, &report)?;
            println!("ps-bench ocr: UNVERIFIED - {err}");
            println!("  results: {}", out.display());
            return Ok(());
        }
    };
    let session_open_ms = session_open_start.elapsed().as_secs_f64() * 1000.0;
    let language = session.language();

    let mut per_image: Vec<ImageResult> = Vec::new();
    let mut pass_reports: Vec<PassReport> = Vec::new();
    let mut first_error = String::new();
    for pass in 1..=passes {
        let paths: Vec<PathBuf> = subset.iter().map(|entry| base_dir.join(&entry.file)).collect();
        let (recognitions, wall_ms) = recognize_pass(&paths, threads, &engine_id, model_dir.as_deref());
        let mut latencies: Vec<f64> = Vec::new();
        let mut cers: Vec<f64> = Vec::new();
        let mut exact = 0usize;
        let mut chars = 0usize;
        let mut errors = 0usize;
        let mut image_errors = 0usize;
        for (entry, recognition) in subset.iter().zip(recognitions) {
            let ms = recognition.ms;
            let recognized = match recognition.outcome {
                Ok(text) => text,
                Err(err) => {
                    if first_error.is_empty() {
                        first_error = err.clone();
                    }
                    image_errors += 1;
                    per_image.push(ImageResult {
                        file: entry.file.clone(),
                        scenario: entry.scenario.clone(),
                        pass,
                        ms,
                        cer: 1.0,
                        errors: 0,
                        chars: 0,
                        exact: false,
                        ground_truth: entry.text.clone(),
                        recognized: format!("ERROR: {err}"),
                    });
                    continue;
                }
            };
            let (cer, errs, n) = cer(&entry.text, &recognized);
            let norm_gt = normalize(&entry.text);
            let norm_rec = normalize(&recognized);
            let is_exact = norm_gt == norm_rec;
            latencies.push(ms);
            cers.push(cer);
            chars += n;
            errors += errs;
            if is_exact {
                exact += 1;
            }
            per_image.push(ImageResult {
                file: entry.file.clone(),
                scenario: entry.scenario.clone(),
                pass,
                ms,
                cer,
                errors: errs,
                chars: n,
                exact: is_exact,
                ground_truth: entry.text.clone(),
                recognized: recognized.chars().take(400).collect(),
            });
        }
        let mut sorted_cer = cers.clone();
        sorted_cer.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let median_cer = if sorted_cer.is_empty() {
            0.0
        } else {
            sorted_cer[sorted_cer.len() / 2]
        };
        pass_reports.push(PassReport {
            pass,
            images: latencies.len(),
            wall_ms,
            images_per_sec: if wall_ms > 0.0 {
                latencies.len() as f64 / (wall_ms / 1000.0)
            } else {
                0.0
            },
            latency: summarize(&latencies),
            mean_cer: if cers.is_empty() {
                0.0
            } else {
                cers.iter().sum::<f64>() / cers.len() as f64
            },
            median_cer,
            exact_rate: if latencies.is_empty() {
                0.0
            } else {
                exact as f64 / latencies.len() as f64
            },
            total_chars: chars,
            total_errors: errors,
            image_errors,
        });
    }

    let recognized_any = per_image
        .iter()
        .any(|r| r.pass == 1 && !r.recognized.starts_with("ERROR:"));
    let failed = !recognized_any;

    // Aggregation uses the last pass (warm) for scenarios; per-image rows keep all passes.
    let warm: Vec<&ImageResult> = per_image.iter().filter(|r| r.pass == passes).collect();
    let mut scen: std::collections::BTreeMap<String, (usize, f64, usize, Vec<f64>)> =
        std::collections::BTreeMap::new();
    for r in &warm {
        let e = scen.entry(r.scenario.clone()).or_insert((0, 0.0, 0, Vec::new()));
        e.0 += 1;
        e.1 += r.cer;
        if r.exact {
            e.2 += 1;
        }
        e.3.push(r.ms);
    }
    let by_scenario = scen
        .into_iter()
        .map(|(scenario, (n, cer_sum, exact, ms))| ScenarioRow {
            scenario,
            images: n,
            mean_cer: if n > 0 { cer_sum / n as f64 } else { 0.0 },
            exact_rate: if n > 0 { exact as f64 / n as f64 } else { 0.0 },
            mean_ms: summarize(&ms),
        })
        .collect();

    let report = OcrReport {
        schema: RESULT_SCHEMA.to_string(),
        kind: "ocr-benchmark".to_string(),
        status: if failed { "failed".to_string() } else { "ok".to_string() },
        reason: if failed {
            format!("{engine_label} recognized no image (language={language}): {first_error}")
        } else {
            format!("{engine_label}, language={language}")
        },
        host: host_info().clone(),
        generated_at_utc: now_utc(),
        command: format!("ps-bench ocr --manifest {} --passes {} --threads {} --engine {} --out {}", manifest_path.display(), passes, threads, engine_id, out.display()),
        engine: engine_label.clone(),
        languages,
        session_open_ms,
        passes: pass_reports,
        by_scenario,
        per_image,
        memory_after: self_memory(),
        limitations: vec![
            "synthetic GDI+ rendered text corpus, not real screenshots/scans; accuracy on real low-quality scans will differ".to_string(),
            "recognized text is truncated to 400 chars in the JSON evidence; CER is computed on the full string".to_string(),
            "accuracy (CER/exact) and speed (ms/images/sec) are separate metrics and must not be combined into one claim".to_string(),
            "session open time is included in pass 1 wall time; pass 2 is the warm measurement".to_string(),
        ],
    };
    write_json(&out, &report)?;

    println!("ps-bench ocr: status={} engine={engine_label} language={language} threads={threads} session_open_ms={session_open_ms:.1}", report.status);
    if failed {
        println!("  FAILED: every image failed; error: {first_error}");
        println!("  results: {}", out.display());
        return Ok(());
    }
    println!("  languages available: {:?}", report.languages);
    for p in &report.passes {
        println!(
            "  pass {}: {} ok / {} failed in {:.0} ms = {:.1} img/s; per-image p50={:.1} p95={:.1} p99={:.1} ms",
            p.pass, p.images, p.image_errors, p.wall_ms, p.images_per_sec, p.latency.p50, p.latency.p95, p.latency.p99
        );
        println!(
            "           accuracy: mean CER={:.4} median CER={:.4} image-exact={:.1}% char-accuracy={:.1}% ({}/{} chars, {} errors)",
            p.mean_cer,
            p.median_cer,
            p.exact_rate * 100.0,
            if p.total_chars > 0 { (p.total_chars - p.total_errors) as f64 / p.total_chars as f64 * 100.0 } else { 0.0 },
            p.total_chars - p.total_errors,
            p.total_chars,
            p.total_errors
        );
    }
    println!("  by scenario (warm pass):");
    for row in &report.by_scenario {
        println!(
            "    {:<14} n={:<3} meanCER={:.4} exact={:.0}% p50={:.1} ms",
            row.scenario,
            row.images,
            row.mean_cer,
            row.exact_rate * 100.0,
            row.mean_ms.p50
        );
    }
    for note in &report.limitations {
        println!("  limit: {note}");
    }
    println!("  results: {}", out.display());
    Ok(())
}

/// Generate the ground-truth corpus.
pub fn run_generate(args: &Args) -> anyhow::Result<()> {
    let out_dir = PathBuf::from(args.get("--out-dir").unwrap_or(".bench/ocr-corpus"));
    let script = PathBuf::from(args.get("--script").unwrap_or("tools/ocr/gen_ocr_corpus.ps1"));
    let count = args.usize_or("--count", 0)?;
    let n = generate_corpus(&out_dir, &script, count)?;
    println!(
        "ps-bench ocr-corpus: {n} images + manifest -> {}",
        out_dir.display()
    );
    Ok(())
}
